const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/lib/physics/gradientReadout.ts": "export function gradientCoordinate(value:number){return Math.round(Math.max(-3,Math.min(3,value))*10000)/10000;}\nexport function gradientAngle(value:number){return (Math.round(((value%360+360)%360)*100)/100)%360;}\nexport function gradientNumber(value:number,digits=4){return (Number(value.toFixed(digits))===0?0:value).toFixed(digits);}\nexport function unitDirection(angle:number){const r=angle*Math.PI/180;return{x:Math.cos(r),y:Math.sin(r)};}\nexport function gradientSubstitution(fieldIndex:number,x:number,y:number,value:number){\n const a=`(${gradientNumber(x)})`,b=`(${gradientNumber(y)})`;\n const expression=[`${a}² + ${b}²`,`${a}² − ${b}²`,`${a}² + 4 × ${b}²`,`${a} × ${b}`][fieldIndex];\n return `φ = ${expression} = ${gradientNumber(value,8)}`;\n}\n", "src/app/minitab/gradient-explorer/page.tsx": "'use client';\nimport { MinitabStage as SimulationStage } from '@/components/simulation/MinitabStage';\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { GradientExplorerCanvas } from '@/components/simulation/GradientExplorerCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { GradientReadout } from '@/components/simulation/GradientReadout';\nimport { gradientCoordinate, gradientAngle } from '@/lib/physics/gradientReadout';\nimport { FIELDS } from '@/lib/physics/gradientField';\n\nconst TEACHER_NOTES = [\n  \"D_â φ = ∇φ · â replaces Chapter 1's slow limit-definition calculation with a single dot product — find ∇φ once at a point, then any directional derivative there is just a dot product away.\",\n  \"∇φ always points in the direction of steepest increase of φ, and its magnitude |∇φ| IS the steepest rate of increase.\",\n  \"Drag the gold handle until it's perpendicular to the green gradient arrow — the readout drops to ≈0. That's exactly why level curves and ∇φ are always perpendicular: moving along a level curve means φ doesn't change at all.\",\n  \"Drag the gold handle to point the opposite way from ∇φ and watch D_âφ hit its most negative value −|∇φ| — steepest decrease.\",\n  \"Try the saddle field x²−y² at the origin: ∇φ=0 there (a stationary point), and every direction gives D_âφ=0 — the classic saddle-point signature.\",\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'For φ=x²+y², find ∇φ at (1,1) and its magnitude.', a: '∇φ=(2x,2y)=(2,2) at (1,1). |∇φ|=√(4+4)=√8≈2.83.' },\n  { q: 'Using the gradient from above, find D_âφ in direction â=(1/√2,1/√2).', a: 'D_âφ=∇φ·â=2(1/√2)+2(1/√2)=4/√2=2√2≈2.83 — matches |∇φ| exactly, since â is aligned with ∇φ here.' },\n  { q: 'For φ=xy, find ∇φ at (2,3) and the direction of steepest ascent.', a: '∇φ=(y,x)=(3,2) at (2,3). Direction: (3,2)/|(3,2)|=(3,2)/√13≈(0.83,0.55). Equivalently θ=atan2(2,3)≈33.69°, anticlockwise from the positive x-axis.' },\n  { q: 'At what points does ∇φ=0 for φ=x²−y²?', a: 'Only at the origin (0,0), where both 2x=0 and −2y=0 — the saddle point.' },\n  { q: 'Explain why moving along a level curve always gives D_âφ=0.', a: 'A level curve is defined by φ=constant, so by definition φ does not change as you move along it — and D_âφ measures exactly that rate of change, so it must be zero in that direction.' },\n];\n\nexport default function GradientExplorerPage() {\n  const [fieldIndex, setFieldIndex] = useState(0);\n  const [point, setPoint] = useState({ x: 1.3, y: 0.9 });\n  const [angleDeg, setAngleDeg] = useState(45);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 480, 480, 520);\n\n  const field = FIELDS[fieldIndex];\n  const gx = field.gx(point.x, point.y), gy = field.gy(point.x, point.y);\n  const gmag = Math.hypot(gx, gy);\n  const rad = (angleDeg * Math.PI) / 180;\n  const dirDeriv = gx * Math.cos(rad) + gy * Math.sin(rad);\n\n  let interpretation = 'D_âφ = ∇φ·â = |∇φ|cosα. α is the angle between ∇φ and â; θ gives the direction of â from the positive x-axis.';\n  const cosAngle = gmag > 1e-6 ? dirDeriv / gmag : 0;\n  if (gmag < 0.05) {\n    interpretation = '∇φ ≈ 0 here — a stationary point. Every direction gives D_âφ ≈ 0.';\n  } else if (Math.abs(cosAngle) > 0.97) {\n    interpretation = cosAngle > 0\n      ? 'â is aligned with ∇φ — steepest increase, D_âφ at its maximum |∇φ|.'\n      : 'â points opposite to ∇φ — steepest decrease, D_âφ at its minimum −|∇φ|.';\n  } else if (Math.abs(dirDeriv) < 0.05 * gmag) {\n    interpretation = \"â is perpendicular to ∇φ — you're moving along the level curve; φ barely changes.\";\n  }\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 1–2</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Gradient &amp; Directional Derivative Explorer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div data-stage-role=\"parameters\" className=\"flex flex-wrap gap-1.5\">\n            {FIELDS.map((f, i) => (\n              <button key={f.name} onClick={() => setFieldIndex(i)}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  fieldIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{f.name}</button>\n            ))}\n          </div>\n\n          <SimulationStage className=\"af-gradient-stage grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              <div ref={canvasBoxRef} className=\"af-minitab-canvas-frame rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <GradientExplorerCanvas\n                  fieldIndex={fieldIndex} point={point} angleDeg={angleDeg}\n                  onPointChange={p=>setPoint({x:gradientCoordinate(p.x),y:gradientCoordinate(p.y)})} onAngleChange={a=>setAngleDeg(gradientAngle(a))}\n                  width={canvasSize.width} height={canvasSize.height}\n                />\n              </div>\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-emerald-100 bg-emerald-50 p-4\">\n                <p className=\"text-xs text-emerald-900 leading-relaxed\">{interpretation}</p>\n              </div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <label className=\"block text-sm text-gray-700\">Scalar field<select aria-label=\"Scalar field\" value={fieldIndex} onChange={e=>setFieldIndex(Number(e.target.value))} className=\"mt-1 w-full rounded-lg border border-gray-300 bg-white p-2\">{FIELDS.map((f,i)=><option key={f.name} value={i}>{f.name}</option>)}</select></label>\n              <GradientReadout fieldIndex={fieldIndex} point={point} angleDeg={angleDeg} onPointChange={setPoint} onAngleChange={setAngleDeg}/>\n              <p className=\"text-[11px] text-gray-400 px-1\">Drag the blue point to move; drag the gold arrowhead to change direction â.</p>\n            </div>\n\n            <div data-stage-role=\"extra\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/components/simulation/GradientReadout.tsx": "'use client';\nimport {useEffect,useState} from 'react';\nimport {FIELDS} from '@/lib/physics/gradientField';\nimport {gradientCoordinate,gradientAngle,gradientNumber as f,gradientSubstitution,unitDirection} from '@/lib/physics/gradientReadout';\ntype Props={fieldIndex:number;point:{x:number;y:number};angleDeg:number;onPointChange:(p:{x:number;y:number})=>void;onAngleChange:(v:number)=>void};\nexport function GradientReadout({fieldIndex,point,angleDeg,onPointChange,onAngleChange}:Props){\n const field=FIELDS[fieldIndex],phi=field.f(point.x,point.y),gx=field.gx(point.x,point.y),gy=field.gy(point.x,point.y),a=unitDirection(angleDeg),directional=gx*a.x+gy*a.y,magnitude=Math.hypot(gx,gy);\n const alpha=magnitude>0?Math.acos(Math.max(-1,Math.min(1,directional/magnitude)))*180/Math.PI:null;\n return <>\n <div className=\"af-gradient-inputs flex flex-wrap items-end gap-3 rounded-xl border border-gray-200 bg-white p-3\">\n  <ExactInput label=\"Point x\" value={point.x} step={0.0001} sanitize={gradientCoordinate} min={-3} max={3} commit={x=>onPointChange({...point,x:gradientCoordinate(x)})}/>\n  <ExactInput label=\"Point y\" value={point.y} step={0.0001} sanitize={gradientCoordinate} min={-3} max={3} commit={y=>onPointChange({...point,y:gradientCoordinate(y)})}/>\n  <ExactInput label=\"Direction θ (degrees)\" value={angleDeg} step={0.01} sanitize={gradientAngle} commit={n=>onAngleChange(gradientAngle(n))}/>\n  <button type=\"button\" className=\"min-h-11 rounded-lg border border-indigo-200 px-3 text-xs font-medium text-indigo-700\" onClick={()=>{onPointChange({x:1,y:1});onAngleChange(90);}}>Set P = (1, 1), θ = 90°</button>\n  <p className=\"text-xs text-gray-600\">Press Enter or Tab to apply typed values.</p>\n </div>\n <div className=\"af-gradient-angle-control rounded-xl border border-gray-200 bg-white p-3\">\n  <label className=\"text-xs text-gray-700\">Direction θ: {f(angleDeg,2)}°<input aria-label=\"Unit vector direction in degrees\" type=\"range\" min={0} max={359.99} step={0.01} value={angleDeg} onChange={e=>onAngleChange(gradientAngle(Number(e.target.value)))} className=\"block w-full accent-amber-600\"/></label>\n </div>\n <div className=\"af-minitab-live-readout af-gradient-readout rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n  <p className=\"mb-2 text-xs font-medium uppercase tracking-wide text-gray-500\">Live readout · {field.name}</p>\n  {[\n   ['Position P = (x, y)',`(${f(point.x)}, ${f(point.y)})`],\n   ['Scalar value φ(P)',f(phi,8)],\n   ['Gradient ∇φ(P)',`(${f(gx)}, ${f(gy)})`],\n   ['Gradient magnitude |∇φ|',f(magnitude)],\n   ['Direction angle θ',`${f(angleDeg,2)}°`],\n   ['Unit vector â = (cos θ, sin θ)',`(${f(a.x)}, ${f(a.y)})`],\n   ['Rate along â: D_âφ',f(directional)],\n  ].map(([label,value])=><div key={label} className=\"af-minitab-stat flex justify-between gap-3 rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-xs text-gray-600\">{label}</span><span className=\"text-xs font-semibold tabular-nums text-indigo-800\">{value}</span></div>)}\n </div>\n <details className=\"af-gradient-working rounded-xl border border-indigo-100 bg-indigo-50 p-3 text-xs leading-6 text-indigo-950\">\n  <summary className=\"cursor-pointer font-semibold\">How these quantities connect · calculation and direction</summary>\n  <p className=\"mt-2 font-mono\">{gradientSubstitution(fieldIndex,point.x,point.y,phi)}</p>\n  <p className=\"mt-2\">θ is measured anticlockwise from the positive x-axis. It gives a direction, not a position or a path. The same direction in component form is â = (cos θ, sin θ), with length 1.</p>\n  <p className=\"mt-2 font-mono\">â = (cos {f(angleDeg,2)}°, sin {f(angleDeg,2)}°) ≈ ({f(a.x)}, {f(a.y)})</p>\n  <p className=\"mt-2 font-mono\">D_âφ = ({f(gx)}) × ({f(a.x)}) + ({f(gy)}) × ({f(a.y)}) ≈ {f(directional)}</p>\n  <p className=\"mt-2\">The alternative formula is D_âφ = |∇φ| cos α. Here α is the angle between ∇φ and â, whereas θ is measured from the x-axis. {alpha===null?'At zero gradient, α is undefined and every directional derivative is zero.':`For these settings, α ≈ ${f(alpha,2)}°.`}</p>\n  <p className=\"mt-2\">P tells you where to evaluate the scalar field. φ is its value there. ∇φ points towards steepest increase; it need not point along â. D_âφ is the rate of change in the direction you chose.</p>\n  <p className=\"mt-2\">For example, θ = 90° gives â = (0, 1). Conversely, a unit vector (aₓ, aᵧ) gives θ = atan2(aᵧ, aₓ), converted to degrees. atan2 uses both signs to choose the correct quadrant.</p>\n  <p className=\"mt-2\">Displayed coordinates are the values used in the calculation, to four decimal places. Dragging uses this same precision. Direction is set to 0.01°. Trigonometric components and the other results are rounded for display.</p>\n </details>\n </>;\n}\nfunction ExactInput({label,value,step,min,max,sanitize,commit}:{label:string;value:number;step:number;min?:number;max?:number;sanitize:(v:number)=>number;commit:(v:number)=>void}){\n const [draft,setDraft]=useState(String(value));useEffect(()=>setDraft(String(value)),[value]);\n function apply(){if(draft.trim()&&Number.isFinite(Number(draft))){const n=sanitize(Number(draft));setDraft(String(n));commit(n);}else setDraft(String(value));}\n return <label className=\"block text-xs text-gray-700\">{label}<input aria-label={label} type=\"number\" min={min} max={max} step={step} value={draft} onChange={e=>setDraft(e.target.value)} onBlur={apply} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();}} className=\"mt-1 block w-32 rounded-lg border border-gray-300 bg-white p-2 text-gray-900\"/></label>;\n}\n", "src/components/simulation/minitab-classroom.css": "/* These rules apply only to expanded Minitab activities. */\n.af-minitab-stage[data-expanded=\"true\"] {\n --af-minitab-plot-height: max(40px, calc(var(--af-stage-canvas-height, 70dvh) - 32px));\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-main { overflow:hidden; }\n.af-minitab-stage[data-expanded=\"true\"] [data-stage-role=\"canvas\"] {\n display:flex; align-items:center; justify-content:center;\n width:100%; height:100%; min-height:0; overflow:hidden; padding:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-canvas-frame {\n display:flex; align-items:center; justify-content:center;\n width:100%; height:100%; min-width:0; min-height:0; padding:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] canvas {\n width:100% !important; height:100% !important;\n max-width:10